    expect(roundTrip.duration==clip.clip.duration&&roundTrip.frames.size()==clip.clip.frames.size(),"exported edited timing");for(std::size_t frame=0;frame<roundTrip.frames.size();++frame)same(roundTrip.frames[frame],clip.clip.frames[frame],.00001f,"export equals preview");
