    auto rawMotion=synthetic;rawMotion.clip.frames.assign(5,doc.base.rest);for(auto& pose:rawMotion.clip.frames)pose[0].t={};rawMotion.clip.referenceFrame={};rawMotion.clip.annotations={{0,0,"animmotion 0 0 0"},{4,0,"animmotion 0 40 80"},{1,0,"start"},{3,0,"finish"}};
    fc::ConverterEditOptions motionEdit;motionEdit.autoCalibration=false;motionEdit.trimIn=1;motionEdit.trimOut=3;motionEdit.speed=2;const auto moved=fc::applyConverterEdits(rawMotion,motionEdit);
    expect((moved.clip.frames.front()[0].t-fc::Vec{0,10,20}).length()<.00001f&&(moved.clip.frames.back()[0].t-fc::Vec{0,30,60}).length()<.00001f,"raw editor motion is baked before trim and speed changes");
    expect(rawMotion.clip.frames.back()[0].t.length()==0&&!fc::converterSourceMotionBaked(rawMotion.clip),"raw editor source remains unchanged");
    expect(std::count_if(moved.clip.annotations.begin(),moved.clip.annotations.end(),[](const auto& event){return event.text==fc::converterSourceMotionMarker&&event.time==0;})==1,"trim preserves a single zero-time marker after all motion keys are outside the interval");
    const auto motionZip=folder/"motion-trimmed.zip";fc::exportConverterEditor(rawMotion,moved,motionZip);const auto motionArchive=unzip(motionZip);fc::ConverterInputClip motionOutput;expect(fc::decodeConverterInput(motionArchive.at(prefix+paths.at("up").first),motionOutput,failure),"trimmed baked motion exports");
    expect(motionOutput.frames.size()==moved.clip.frames.size(),"trimmed baked motion retains preview sampling");for(std::size_t frame=0;frame<motionOutput.frames.size();++frame)same(motionOutput.frames[frame],moved.clip.frames[frame],.00001f,"trimmed baked export matches preview without double application");
    std::vector<std::string> motionWarnings;const auto motionAgainBytes=fc::writeConverterHkx(motionOutput,doc.base,motionWarnings);fc::ConverterInputClip motionAgain;expect(fc::decodeConverterInput(motionAgainBytes,motionAgain,failure),"trimmed motion reimports");expect(motionAgain.annotations.size()==motionOutput.annotations.size(),"trimmed motion reimport does not add another marker");for(std::size_t frame=0;frame<motionAgain.frames.size();++frame)same(motionAgain.frames[frame],motionOutput.frames[frame],.00001f,"trimmed motion reimport preserves all transforms");
    expect(nlohmann::json::parse(archive.at(prefix+paths.at("up").second))==clip.config,"export equals edited contact metadata");expect(read(input)==savedInput&&read(base/"pack.json")==savedManifest,"editor preserves source and base");
    rejects([&]{fc::exportConverterEditor(synthetic,clip,archivePath);},"existing output is protected");expect(read(archivePath).size()>0,"existing output remains intact");
    auto invalid=edited;invalid.trimOut=.5f;rejects([&]{fc::applyConverterEdits(synthetic,invalid);},"reverse trim rejected");invalid=edited;invalid.speed=0;rejects([&]{fc::applyConverterEdits(synthetic,invalid);},"zero speed rejected");
    invalid=edited;invalid.bones={{97,{20,0,0},0,1,.1f}};rejects([&]{fc::applyConverterEdits(synthetic,invalid);},"camera bone correction rejected");invalid=edited;invalid.bones={{32,{45,45,45},0,1,.1f}};rejects([&]{fc::applyConverterEdits(synthetic,invalid);},"combined excessive bone rotation rejected");
    invalid=edited;invalid.contacts={{4,0,1,.1f,1}};rejects([&]{fc::applyConverterEdits(synthetic,invalid);},"unknown contact rejected");invalid=edited;invalid.makeInPlaceAxes.x=.5f;rejects([&]{fc::applyConverterEdits(synthetic,invalid);},"in-place axis is a boolean selection");
    for(unsigned bone:{42u,43u,46u,47u,48u,49u,60u,61u,62u,63u,64u,65u,66u}){expect(!fc::converterEditableBone(doc.base,bone),"runtime-owned attachment is unavailable for correction");invalid=edited;invalid.bones={{bone,{10,0,0},0,1,.1f}};rejects([&]{fc::applyConverterEdits(synthetic,invalid);},"runtime-owned attachment edit rejected");}expect(fc::converterEditableBone(doc.base,32),"body forearm remains editable");
    auto staticDoc=synthetic;staticDoc.clip.frames.assign(2,doc.base.rest);staticDoc.clip.duration=1;staticDoc.clip.annotations.clear();staticDoc.clip.referenceFrame={};fc::ConverterEditOptions staticEdit;staticEdit.autoCalibration=false;staticEdit.bones={{32,{15,0,0},0,1,.2f}};staticEdit.contacts={{0,0,1,.2f,0}};const auto staticEdited=fc::applyConverterEdits(staticDoc,staticEdit);
    expect(staticEdited.clip.frames.size()>=65,"two-frame source gains bounded correction samples");expect(fc::angleBetween(fc::sampleConverterEditor(staticEdited,.5f)[32].q,doc.base.rest[32].q)>.25f,"static source correction is visible at midpoint");expect(fc::sampleConverterContacts(staticEdited,.5f)[0]==0,"static source contact correction is represented");
    const auto staticZip=folder/"static-edited.zip";fc::exportConverterEditor(staticDoc,staticEdited,staticZip);const auto staticArchive=unzip(staticZip);fc::ConverterInputClip staticRoundTrip;expect(fc::decodeConverterInput(staticArchive.at(prefix+paths.at("up").first),staticRoundTrip,failure),"edited static source exports");same(staticRoundTrip.frames[staticRoundTrip.frames.size()/2],staticEdited.clip.frames[staticEdited.clip.frames.size()/2],.00001f,"static correction export equals preview");
