    special.contacts={{0,0,1,.1f,1}};rejects([&]{fc::applyConverterEdits(mantle,special);},"generic contact edit cannot pretend to change special action");special.contacts.clear();special.windows={{"replantSample",.8f,.8f}};rejects([&]{fc::applyConverterEdits(mantle,special);},"inconsistent mantle calibration rejected");
    auto side=fc::loadConverterEditor(base/paths.at("contextHopLeft").first,base/"pack.json","contextHopLeft");special.windows={{"vertical",0,.1f}};rejects([&]{fc::applyConverterEdits(side,special);},"vertical phase cannot overlap loaded source hands");
