    const auto sideEdited=fc::applyConverterEdits(side,special);expect(sideEdited.config.at("path")[1][2]==sideGeometry.path[1][2],"bounded movement path edit changes actual runtime metadata");fc::exportConverterEditor(side,sideEdited,folder/"path.zip");special.geometry->travel.x=10;rejects([&]{fc::applyConverterEdits(side,special);},"side travel cannot point at the wrong endpoint");special.geometry=sideGeometry;special.geometry->path.back()[2]=1;rejects([&]{fc::applyConverterEdits(side,special);},"movement path end must remain anchored");
    auto geometry=identity;geometry.geometry=fc::ConverterGeometryEdit{123,4,{0,0,4},{}};const auto geometryEdited=fc::applyConverterEdits(doc,geometry);expect(geometryEdited.config.at("stride")==123&&geometryEdited.config.at("height")==4,"ordinary stride and height edit");geometry.geometry->stride=501;rejects([&]{fc::applyConverterEdits(doc,geometry);},"movement scalar bounds retained");
    fc::ConverterEditOptions automatic;const auto calibrated=fc::applyConverterEdits(doc,automatic);expect(calibrated.confidence>=0&&calibrated.confidence<=1&&!calibrated.phaseMap.empty(),"automatic calibration exposes confidence and phase mapping");expect(calibrated.config.at("file")==doc.templateConfig.at("file")&&calibrated.config.at("slot")=="up","automatic calibration preserves slot identity");fc::exportConverterEditor(doc,calibrated,folder/"automatic.zip");
    auto down=fc::loadConverterBaseEditor(base/"pack.json","down");
    for(const float target:{0.f,1.f}){fc::ConverterEditOptions bounded;bounded.contacts={{0,0,1,.01f+(.3f-.01f)*.138f,target}};const auto output=fc::applyConverterEdits(down,bounded);
        for(const auto& row:output.config.at("contacts"))for(const auto& value:row){const float weight=value.get<float>();expect(std::isfinite(weight)&&weight>=0&&weight<=1,"contact edit interpolation remains bounded");}
        for(std::size_t frame=0;frame<output.clip.frames.size();++frame)for(const auto weight:fc::sampleConverterContacts(output,output.clip.duration*float(frame)/float(output.clip.frames.size()-1)))expect(weight>=0&&weight<=1,"edited timeline samples remain bounded");
        fc::exportConverterEditor(down,output,folder/(target==0?"down-release.zip":"down-support.zip"));
    }
    for(const bool automatic:{false,true})for(const float weight:{-.0000001f,1.0000007f}){auto invalidContacts=down;invalidContacts.templateConfig["contacts"][0][0]=weight;fc::ConverterEditOptions bounded;bounded.autoCalibration=automatic;bounded.contacts={{0,0,1,.05f,1}};rejects([&]{fc::applyConverterEdits(invalidContacts,bounded);},"out-of-range source weights are rejected rather than repaired");}
    auto changed=read(input);changed.back()^=1;write(input,changed);const auto rejectedOutput=folder/"changed.zip";rejects([&]{fc::exportConverterEditor(doc,calibrated,rejectedOutput);},"changed input invalidates editor session");expect(!std::filesystem::exists(rejectedOutput),"changed input publishes nothing");write(input,savedInput);
    changed=read(base/paths.at("up").second);changed.push_back(' ');const auto originalMetadata=read(base/paths.at("up").second);write(base/paths.at("up").second,changed);rejects([&]{fc::exportConverterEditor(doc,calibrated,rejectedOutput);},"changed base invalidates editor session");expect(!std::filesystem::exists(rejectedOutput),"changed base publishes nothing");write(base/paths.at("up").second,originalMetadata);
